export type IconName = keyof typeof ICONS;

export function hasIcon(name: string): name is IconName {
  return Object.prototype.hasOwnProperty.call(ICONS, name);
}

interface AppIconProps {
  name: IconName;
  size?: number;
  color?: string;
  style?: StyleProp<ViewStyle>;
}

/** Vector icon matching the original `icon_*.xml` drawables (24dp grid). */
export function AppIcon({ name, size = 24, color = '#000', style }: AppIconProps) {
  const def = ICONS[name];
  if (!def) return null;
  return (
    <Svg width={size} height={size} viewBox={def.viewBox} style={style}>
      {def.paths.map((p, i) => (
        <Path key={i} d={p.d} fill={p.fill ?? color} fillRule={p.fillRule} />
      ))}
    </Svg>
  );
}
